  - macapp/WorkroomApp/Core/VCSSyncPresentation.swift
  - macapp/WorkroomApp/Core/VCSWriting.swift
  - macapp/WorkroomApp/Views/VCSFailureSheet.swift
  - macapp/WorkroomApp/Views/VCSToolbar.swift
  - macapp/WorkroomAppTests/AppStoreContentNavigationTests.swift
  - macapp/WorkroomAppTests/BranchLabelTests.swift
  - macapp/WorkroomAppTests/RemoteStateModelTests.swift
